create or replace function public.render_street_notification_email(p_title text,p_body text,p_kind text) returns text language plpgsql immutable set search_path='' as $fn$
declare safe_title text; safe_body text; category_label text;
begin
 safe_title:=replace(replace(replace(coalesce(p_title,'Street Goose 034'),'&','&amp;'),'<','&lt;'),'>','&gt;');
 safe_body:=replace(replace(replace(coalesce(p_body,''),'&','&amp;'),'<','&lt;'),'>','&gt;');
 category_label:=case p_kind when 'orderUpdates' then 'SEUS PEDIDOS' when 'levelUp' then 'SUA EVOLUÇÃO' when 'rankingUp' then 'SEU LUGAR NA STREET' when 'rewardUnlocked' then 'SUAS CONQUISTAS' when 'couponUnlocked' then 'SEUS BENEFÍCIOS' when 'postApproved' then 'SUA COMUNIDADE' when 'newsletter' then 'NOVIDADES DA STREET' when 'inactivity' then 'SUA STREET TE ESPERA' when 'adminAlerts' then 'PAINEL DA LOJA' else 'SUA STREET GOOSE' end;
 return format($email$<!DOCTYPE html><html lang="pt-BR" dir="ltr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="X-UA-Compatible" content="IE=edge"><title>%s</title></head><body style="margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;background-color:#f1eee7"><span lang="pt-BR" dir="ltr" style="display:none;font-size:1px;line-height:1px;color:#f1eee7;max-height:0;overflow:hidden">%s</span><table lang="pt-BR" dir="ltr" role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f1eee7"><tr><td align="center" style="padding-top:32px;padding-right:16px;padding-bottom:32px;padding-left:16px"><table lang="pt-BR" dir="ltr" role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background-color:#ffffff"><tr><td bgcolor="#151619" align="center" style="padding-top:24px;padding-right:24px;padding-bottom:24px;padding-left:24px"><img src="https://www.streetgoose034.com.br/brand/street-goose-email.png" width="240" height="64" border="0" alt="Street Goose 034" style="display:block"><p style="font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:18px;letter-spacing:3px;color:#d7bd88;margin-bottom:0">STREET GOOSE 034</p></td></tr><tr><td style="padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px"><p style="font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:20px;letter-spacing:2px;color:#705529">%s</p><h1 style="font-family:Arial,Helvetica,sans-serif;font-size:28px;line-height:36px;color:#18191b;margin-top:12px;margin-bottom:20px">%s</h1><p style="font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:28px;color:#464744;margin-top:0;margin-bottom:24px">%s</p><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#d7bd88" style="border-radius:8px"><a href="https://www.streetgoose034.com.br/conta" style="display:inline-block;padding-top:16px;padding-right:24px;padding-bottom:16px;padding-left:24px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:22px;font-weight:bold;color:#18191b;text-decoration:none">Abrir minha conta</a></td></tr></table><p style="font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:22px;color:#666760;margin-top:24px;margin-bottom:0">Este aviso acompanha uma atividade da sua conta ou uma comunicação que você escolheu receber.</p></td></tr><tr><td bgcolor="#f8f6f1" style="padding-top:22px;padding-right:28px;padding-bottom:22px;padding-left:28px"><p style="font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:20px;color:#666760;margin-top:0;margin-bottom:8px">Sua presença. Sua próxima conquista.</p><p style="font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:20px;color:#666760;margin-top:0;margin-bottom:0">Você controla seus canais e tipos de aviso em <a href="https://www.streetgoose034.com.br/conta" style="font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:20px;color:#705529">Conta → Preferências</a>. Para atendimento, fale com a equipe pelo site.</p></td></tr></table></td></tr></table></body></html>$email$,safe_title,left(safe_body,90),category_label,safe_title,replace(safe_body,chr(10),'<br>'));
end; $fn$;
revoke all on function public.render_street_notification_email(text,text,text) from public,anon,authenticated;
